let initialGuides=[
 {id:'g1',type:0,title:'전원이 켜지지 않아요',steps:['전원 케이블과 멀티탭 연결 상태를 확인해주세요. 멀티탭의 전원 표시등이 켜져 있나요?','연결 상태를 확인한 뒤 PC 전원 버튼을 한 번 눌러주세요. 전원 표시등이나 팬의 작동 여부를 확인해주세요.']},
 {id:'g2',type:0,title:'컴퓨터가 느리거나 멈춰요',steps:['진행 중인 작업을 저장하고 사용하지 않는 프로그램을 닫아주세요. 응답하지 않는 프로그램이 있는지 확인해주세요.','진료 업무에 영향이 없는지 먼저 확인해주세요. 저장하지 않은 작업이 사라질 수 있습니다. 재시작이 가능한 경우 PC를 다시 시작해주세요.']},
 {id:'g3',type:0,title:'키보드·마우스가 작동하지 않아요',steps:['키보드·마우스의 연결 상태를 확인해주세요. 무선 제품은 배터리와 전원 상태도 확인해주세요.','진행 중인 작업에 영향이 없는지 확인한 후 USB 연결을 다시 연결해주세요.']},
 {id:'g4',type:1,title:'화면에 신호 없음이 표시돼요',steps:['PC와 모니터 전원이 모두 켜져 있는지 확인해주세요. 모니터 전원 표시등을 확인해주세요.','모니터의 영상 케이블 연결 상태와 입력 소스(HDMI·DP 등)가 연결된 단자와 같은지 확인해주세요.']},
 {id:'g5',type:1,title:'화면이 깜빡이거나 색상이 이상해요',steps:['모니터 영상 케이블이 느슨하게 연결되어 있지 않은지 확인해주세요.','모니터 메뉴에서도 같은 증상이 발생하는지 확인해주세요. 반복되면 전산 지원이 필요합니다.']},
 {id:'g6',type:2,title:'프린터 출력이 안 돼요',steps:['프린터 전원과 화면의 오류 메시지를 확인해주세요. 용지와 토너 상태도 확인해주세요.','출력 화면에서 선택한 프린터가 실제 사용할 장비인지 확인해주세요. 오프라인 또는 오류 문구가 표시되면 기록해주세요.']},
 {id:'g7',type:2,title:'용지가 걸렸어요',steps:['프린터 화면에 표시된 용지 걸림 위치와 해당 장비의 사용자 안내를 확인해주세요.','사용자에게 허용된 덮개만 열고 안내에 따라 보이는 용지를 조심히 제거해주세요. 뜨거운 부품을 만지거나 용지를 강하게 잡아당기지 마세요. 어려우면 조치를 중단해주세요.']},
 {id:'g8',type:3,title:'라벨이 나오지 않아요',steps:['프린터 전원과 오류 표시를 확인해주세요. 라벨 용지 및 리본 잔량과 장착 상태를 확인해주세요.','선택한 출력 장비가 맞는지 확인해주세요. 환자정보가 들어간 시험 출력을 반복하지 마세요.']},
 {id:'g9',type:3,title:'라벨 위치가 어긋나요',steps:['라벨 규격이 기존에 사용하던 규격과 같은지, 용지가 비뚤게 장착되지 않았는지 확인해주세요.','출력 위치 또는 바코드에 문제가 있는 라벨은 사용을 중단해주세요. 정상 출력·인식 확인 전 임상 업무에 사용하지 마세요.']}
];
const now=()=>new Date().toISOString();
const date=s=>new Date(s).toLocaleString('ko-KR',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Seoul'});
function seed(){let t=Date.now();return [
 ['프린터 출력이 안 돼요',2,'외래간호팀','외래 2층 간호사실','접수',null,true,1],
 ['화면에 신호 없음이 표시돼요',1,'외래간호팀','외래 1층 103 진료실','처리 중','김전산',false,3],
 ['라벨 위치가 어긋나요',3,'진단검사의학팀','본관 3층 채혈실','접수',null,false,5],
 ['컴퓨터가 느리거나 멈춰요',0,'외래간호팀','외래 2층 처치실','완료','이전산',false,22],
 ['전원이 켜지지 않아요',0,'원무팀','본관 1층 수납창구','완료','김전산',false,30],
 ['라벨이 나오지 않아요',3,'진단검사의학팀','검체 접수실','완료','이전산',false,46],
 ['용지가 걸렸어요',2,'외래간호팀','외래 3층 접수대','처리 중','이전산',false,52],
 ['화면이 깜빡이거나 색상이 이상해요',1,'원무팀','입원 수속 창구','완료','김전산',false,70]
 ].map((x,i)=>({id:'IT-'+(new Date().getFullYear())+'-'+String(128-i).padStart(4,'0'),title:x[0],type:x[1],dept:x[2],location:x[3],status:x[4],assignee:x[5],urgent:x[6],created:new Date(t-x[7]*3600000).toISOString(),completed:x[4]==='완료'?new Date(t-(x[7]-2)*3600000).toISOString():null,name:i===0?'김간호':'박직원',user:i===0?'N1024':'N10'+i,phone:'내선 1234',asset:'',description:'업무 중 장비 이상이 발생했습니다.',reason:x[6]?'진료 중단':'',history:[],images:[],events:[{text:'장애가 접수되었습니다.',at:new Date(t-x[7]*3600000).toISOString()}],resolution:x[4]==='완료'?'연결 상태 점검 및 출력 테스트 후 정상 동작을 확인했습니다.':''}));}
let data;try{data=JSON.parse(localStorage.getItem('oncare-v1'))}catch{};
if(!data||!Array.isArray(data.requests))data={requests:seed(),guides:initialGuides,solved:0,notifications:[]};
const bootstrapImageResult=bootstrapGuideImages(data);
const sampleRequestResult=installSampleRequests(data,initialGuides);
if(!data.toner){data.toner=Toner.create();try{localStorage.setItem("oncare-v1",JSON.stringify(data));}catch{}}
const tonerHistoryResult=installTonerHistory(data);
const todayDemoResult=installTodayDemo(data,initialGuides);
let signedIn=false,pendingPage='home';
function requireLogin(target='home'){if(signedIn)return true;pendingPage=target;glassLogin();return false;}
let role='staff',page='intro',filters={q:'',status:'',type:'',dept:'',assignee:'',symptom:'',urgent:'',from:'',to:''},wizard=null,activeId=null,editId=null;
function save(){localStorage.setItem('oncare-v1',JSON.stringify(data))}
function user(){return role==='staff'?{name:'김간호',dept:'외래간호팀',id:'N1024'}:{name:role==='admin2'?'이전산':'김전산',dept:'전산팀',id:role==='admin2'?'IT02':'IT01'}}
function admin(){return role!=='staff'}
function visible(){return data.requests.filter(r=>admin()||r.dept===user().dept||r.user===user().id)}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function notify(message,target='staff'){data.notifications.unshift({id:crypto.randomUUID(),message,target,at:now(),read:false});save()}
function mynotes(){return data.notifications.filter(n=>n.target==='all'||(n.target==='admin'&&admin())||(n.target==='staff'&&!admin()))}
function tag(status){return `<span class="tag ${status==='접수'?'pending':status==='처리 중'?'progress':'done'}">${status}</span>`}
function nav(n){if(n!=='intro'&&!requireLogin(n))return;page=n;filters={q:'',status:'',type:'',dept:'',assignee:'',symptom:'',urgent:'',from:'',to:''};render();if(n==='intro')window.scrollTo({top:0,behavior:'instant'});}
function shell(){const u=user();return `<aside class="sidebar"><div class="brand hospital-brand"><div class="hospital-logo"><img src="data:image/svg+xml;base64," alt="일산차병원" width="130" height="18"></div><div class="hospital-service">온케어 <span>IT 지원센터</span><small>HOSPITAL IT SUPPORT</small></div></div><div class="navlabel">WORKSPACE</div><nav>${[['intro','home','홈페이지'],['home','home','대시보드'],['help','pc','장애 해결 가이드'],['requests','list',admin()?'전체 신청현황':'우리 부서 신청현황'],['toner','printer','토너 신청·재고'],...(admin()?[['stats','chart','통계 분석'],['weekly','list','주간 취합보고'],['monthly','list','월간 취합보고'],['manage','book','가이드 관리'],['catalog','pc','장비 제조사·모델 관리']]:[])].map(([p,i,t])=>`<button class="navbtn ${page===p?'active':''}" data-nav="${p}">${icon(i)}${t}${p==='requests'?`<span class="navnum">${visible().filter(r=>r.status!=='완료').length}</span>`:''}</button>`).join('')}</nav><div class="sidebottom"><div class="support"><strong>도움이 더 필요하신가요?</strong><p>단계별 안내를 따라 확인하고<br>해결되지 않으면 접수해주세요.</p><button class="textbtn" data-action="urgent">긴급 장애 바로 접수 ↗</button></div><div class="sidefooter">함께 만드는 원활한 진료 환경<br>일산차병원 · ONCARE IT SUPPORT</div></div></aside><main class="main"><header class="topbar"><div class="crumb">일산차병원 IT 지원센터 &nbsp; / &nbsp; <b>${({weekly:'주간 취합보고',monthly:'월간 취합보고',catalog:'장비 제조사·모델 관리',toner:'토너 신청·재고',home:'대시보드',help:'장애 해결 가이드',requests:'신청현황',stats:'통계 분석',manage:'가이드 관리'})[page]}</b></div><div class="topright"><span class="pill"><span class="dot"></span>병원 내부망 서비스</span><select class="role" id="role" aria-label="시연 역할 선택"><option value="staff" ${role==='staff'?'selected':''}>직원 · 김간호</option><option value="admin" ${role==='admin'?'selected':''}>전산 · 김전산</option><option value="admin2" ${role==='admin2'?'selected':''}>전산 · 이전산</option></select><button class="bell" data-action="notifications" aria-label="알림">${icon('bell')}${mynotes().some(n=>!n.read)?'<i></i>':''}</button><div class="avatar">${u.name.slice(0,1)}</div><div class="user">${u.name} <small>님</small><br><small>${u.dept}</small></div></div></header><div class="content" id="content"></div></main>`}
function heading(title,subtitle,action=''){return `<div class="titleline"><div><div class="eyebrow">ONCARE SUPPORT CENTER</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`}
function metrics(rows){let done=rows.filter(r=>r.status==='완료').length;return `<div class="cards">${[['전체 신청',rows.length,'건','list','누적 접수된 장애 신청'],['접수 대기',rows.filter(r=>r.status==='접수').length,'건','clock','담당자 확인을 기다리고 있어요'],['처리 중',rows.filter(r=>r.status==='처리 중').length,'건','pc','전산 담당자가 확인하고 있어요'],['처리 완료',done,'건','check',`<em>${rows.length?Math.round(done/rows.length*100):0}%</em> 의 신청이 해결되었어요`]].map(([l,v,u,i,f])=>`<div class="metric"><div class="metriclabel">${l}${icon(i)}</div><div class="metricvalue">${v}<small>${u}</small></div><div class="metricfoot">${f}</div></div>`).join('')}</div>`}
