  '<rect x="17" y="7" width="30" height="25" rx="4" fill="#c5eee2"/><path d="M23 14h18m-18 6h12" stroke="#69b49b" stroke-width="2.5" stroke-linecap="round"/><rect x="7" y="23" width="50" height="27" rx="8" fill="#239b80"/><rect x="12" y="28" width="40" height="13" rx="4" fill="#66c5aa"/><circle cx="45" cy="34" r="2" fill="#e4fff4"/><rect x="17" y="39" width="30" height="8" rx="3" fill="#147460"/><path d="M19 44h26v14H19z" fill="#f0fcf6"/><path d="M25 49h14m-14 5h10" stroke="#a0d9c2" stroke-width="2" stroke-linecap="round"/>',
