function equipment(){return `<div class="equipment equipment-modern">${types.map((t,i)=>`<button class="equip equip-modern device-${i}" data-type="${i}"><span class="equip-arrow" aria-hidden="true">↗</span><span class="equip-visual">${equipmentArtwork(i)}</span><strong>${t}</strong><small>${['전원 · 작동 · 속도','화면 · 신호 · 연결','출력 · 용지 · 연결','라벨 · 바코드 · 위치'][i]}</small></button>`).join('')}</div>`}

function table(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>접수번호</th><th>장비 / 증상</th><th>부서 · 발생 위치</th><th>상태</th><th>담당자</th><th>접수일시</th></tr></thead><tbody>${rows.map(r=>`<tr data-detail="${r.id}" tabindex="0" role="button" aria-label="${esc(r.title)} 상세"><td>${r.id}</td><td class="tdmain">${r.urgent?'<span class="tag urgent">긴급</span>':''}${esc(r.title)}<small>${types[r.type]}${r.brand?' · '+esc(r.brand):''}${r.model?' · '+esc(r.model):''}</small></td><td>${esc(r.dept)}<div style="color:#9caaaf;font-size:10px;margin-top:5px">${esc(r.location)}</div></td><td>${tag(r.status)}</td><td>${esc(r.assignee||'미배정')}</td><td>${date(r.created)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">조회 조건에 해당하는 신청이 없습니다.</div>'}
function home(){let rows=visible();return `<section class="welcome-banner" aria-label="온케어 대시보드 안내"><div class="welcome-message"><div class="eyebrow">ILSAN CHA HOSPITAL · ONCARE</div><h1>${esc(user().name)}님, 안녕하세요 👋</h1><p class="subtitle">오늘도 안정적인 병원 IT 환경을 위해 함께합니다.</p></div><p class="welcome-motto">IT가 더 건강한<br>의료를 만듭니다.</p><button class="btn danger welcome-urgent" data-action="urgent">${icon('alert')}긴급 장애 접수</button></section>`+dashboardMetrics(rows)+tonerDashboard()+`<section class="hero"><div><div class="eyebrow">SELF-SERVICE GUIDE</div><h2>잠깐의 확인으로, 다시 원활하게.</h2><p>장비와 증상을 선택하고 단계별 해결 방법을 확인해보세요.<br>해결되지 않는 문제는 전산 담당자에게 바로 이어집니다.</p><button class="btn primary" data-nav="help">장애 해결 시작하기 ${icon('arrow')}</button></div><div class="hero-art"><div class="monitor">✓</div><span class="spark">✧</span></div></section><div class="grid-two"><section class="panel"><div class="panelhead"><h2>어떤 장비에 문제가 있나요?</h2><span class="textbtn">장비 선택</span></div>${equipment()}<div class="helper">ⓘ &nbsp; 전원 분해나 관리자 설정 변경이 필요한 작업은 전산 담당자가 도와드립니다.</div></section><section class="panel"><div class="panelhead"><h2>자주 찾는 해결 가이드</h2><span class="trend">QUICK GUIDE</span></div>${[data.guides[5],data.guides[0],data.guides[3],data.guides[8]].filter(Boolean).map(g=>`<button class="guide-row" data-guide="${g.id}"><div class="miniicon">${icon(typeicons[g.type])}</div>${esc(g.title)}<span>›</span></button>`).join('')}</section></div><section class="panel tablepanel dashboard-recent"><div class="panelhead"><h2>${admin()?'최근 접수된 신청':'우리 부서 최근 신청'} <span class="textbtn" style="margin-left:8px">${rows.length}</span></h2><button class="textbtn" data-nav="requests">전체 보기 →</button></div>${table(rows.slice().sort((a,b)=>new Date(b.created)-new Date(a.created)).slice(0,4))}</section>`}
function help(){return heading('장애 해결 가이드','문제가 생긴 장비를 선택하세요. 간단한 확인부터 차근차근 안내합니다.',`<button class="btn danger" data-action="urgent">${icon('alert')}긴급 접수</button>`)+`<section class="panel">${equipment()}<div class="notice warm">진료 중단·여러 장비의 동시 장애는 자가 조치 없이 긴급 접수할 수 있습니다. 타는 냄새나 연기가 발생하면 사용을 중단하고 전산에 연락해주세요.</div></section><div style="height:24px"></div><div class="grid-two">${types.map((t,i)=>`<section class="panel"><div class="panelhead"><h2>${t}</h2>${icon(typeicons[i])}</div>${data.guides.filter(g=>g.type===i).map(g=>`<button class="guide-row" data-guide="${g.id}">${esc(g.title)}<span>→</span></button>`).join('')}</section>`).join('')}</div>`}
function filtered(){return visible().filter(r=>(!filters.q||[r.id,r.title,r.location,r.asset,r.name,r.brand,r.model].join(' ').toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.symptom||r.title===filters.symptom)&&(!filters.status||r.status===filters.status)&&(!filters.type||r.type===Number(filters.type)-1)&&(!filters.dept||r.dept===filters.dept)&&(!filters.assignee||r.assignee===filters.assignee)&&(!filters.urgent||r.urgent)&&(!filters.from||r.created>=new Date(filters.from+'T00:00:00+09:00').toISOString())&&(!filters.to||r.created<=new Date(filters.to+'T23:59:59.999+09:00').toISOString()))}
function options(values,current,all){return `<option value="">${all}</option>`+values.map(v=>`<option ${current===v?'selected':''}>${esc(v)}</option>`).join('')}
function filterbar(stats=false){return `<div class="filters"><input id="search" placeholder="접수번호, 증상, 위치 검색" aria-label="신청 검색" value="${esc(filters.q)}"><select data-filter="status" aria-label="상태">${options(['접수','처리 중','완료'],filters.status,'전체 상태')}</select><select data-filter="type" aria-label="장비"><option value="">전체 장비</option>${types.map((t,i)=>`<option value="${i+1}" ${filters.type==String(i+1)?'selected':''}>${t}</option>`).join('')}</select><select data-filter="symptom" aria-label="증상">${options([...new Set(visible().map(r=>r.title))],filters.symptom,'전체 증상')}</select><select data-filter="dept" aria-label="부서">${options([...new Set(visible().map(r=>r.dept))],filters.dept,'전체 부서')}</select>${admin()?`<select data-filter="assignee" aria-label="담당자">${options(['김전산','이전산'],filters.assignee,'전체 담당자')}</select>`:''}<select data-filter="urgent" aria-label="긴급 여부"><option value="">전체 우선순위</option><option value="yes" ${filters.urgent?'selected':''}>긴급 장애</option></select><input style="flex:0" type="date" data-filter="from" aria-label="접수 시작일" value="${filters.from}"><input style="flex:0" type="date" data-filter="to" aria-label="접수 종료일" value="${filters.to}"><button class="btn" data-action="resetfilters">초기화</button></div>`}
function requests(){return heading(admin()?'전체 신청현황':'우리 부서 신청현황',admin()?'접수된 장애를 확인하고 담당자를 지정해 처리하세요.':'본인과 같은 부서의 신청 및 처리 진행 상황을 확인하세요.',`<button class="btn primary" data-nav="help">${icon('plus')}장애 해결 시작</button>`)+filterbar()+`<section class="panel tablepanel"><div class="panelhead"><h2>신청 목록 <span class="textbtn">${filtered().length}건</span></h2><span class="textbtn">${admin()?'긴급 미완료 우선 · 접수 순':'최근 접수일 순'}</span></div>${table(filtered().sort((a,b)=>admin()?(Number(b.urgent&&b.status!=='완료')-Number(a.urgent&&a.status!=='완료')||new Date(a.created)-new Date(b.created)):new Date(b.created)-new Date(a.created)))}</section>`}
function stats(){if(!admin())return '';let rows=filtered(),done=rows.filter(r=>r.status==='완료'),avg=done.length?done.reduce((s,r)=>s+(new Date(r.completed)-new Date(r.created))/3600000,0)/done.length:0;let counts=types.map((t,i)=>rows.filter(r=>r.type===i).length),max=Math.max(...counts,1),dailyMax=Math.max(1,...Array.from({length:7},(_,i)=>{let day=new Date();day.setDate(day.getDate()-(6-i));let key=day.toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'});return rows.filter(r=>new Date(r.created).toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'})===key).length}));return heading('통계 분석','접수일 기준으로 집계한 장애 현황입니다. 야간·휴일을 포함한 처리시간을 표시합니다.',`<button class="btn" data-action="export">${icon('download')}엑셀 다운로드</button>`)+filterbar(true)+metrics(rows)+`<div class="grid-two"><section class="panel"><div class="panelhead"><h2>장비별 장애 접수</h2><span class="textbtn">${rows.length}건 기준</span></div>${types.map((t,i)=>`<div class="barrow"><span>${t}</span><div class="bartrack"><div class="bar" style="width:${counts[i]/max*100}%"></div></div><b>${counts[i]}</b></div>`).join('')}</section><section class="panel"><h2>처리 성과</h2><div style="display:flex;gap:45px;padding:25px 0"><div><div class="subtitle">평균 처리시간</div><div class="metricvalue">${done.length?avg.toFixed(1):'—'}<small>시간</small></div></div><div><div class="subtitle">자가 해결 세션</div><div class="metricvalue">${data.solved}<small>건</small></div></div></div><div class="helper">자가 해결은 전체 시연 세션 기준이며 접수 건수에 포함되지 않습니다.</div></section></div><div class="grid-two"><section class="panel"><h2>최근 7일 접수 추이</h2><div class="chart">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(6-i));let label=d.toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'}),n=rows.filter(r=>new Date(r.created).toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'})===label).length;return `<div class="chartcol"><span>${n}</span><i style="height:${Math.max(Math.round(n/dailyMax*115),3)}px"></i><small>${label.slice(5)}</small></div>`}).join('')}</div></section><section class="panel"><h2>담당자별 완료 건수</h2>${['김전산','이전산'].map(a=>`<div class="barrow"><span>${a}</span><div class="bartrack"><div class="bar" style="width:${done.filter(r=>r.assignee===a).length/Math.max(done.length,1)*100}%"></div></div><b>${done.filter(r=>r.assignee===a).length}</b></div>`).join('')}<div class="helper">완료 시점의 담당자 기준</div></section></div><section class="panel"><div class="panelhead"><h2>부서별 접수 현황</h2></div>${[...new Set(rows.map(r=>r.dept))].map(d=>`<div class="guide-row">${esc(d)}<span>${rows.filter(r=>r.dept===d).length}건</span></div>`).join('')||'<p class="empty">집계 대상 없음</p>'}<div class="panelhead" style="margin-top:28px"><h2>자주 발생하는 증상</h2><span class="textbtn">현재 필터 기준</span></div>${Object.entries(rows.reduce((a,r)=>(a[r.title]=(a[r.title]||0)+1,a),{})).sort((a,b)=>b[1]-a[1]).map(([t,n],i)=>`<div class="guide-row"><b style="color:#8eaaa1">${String(i+1).padStart(2,'0')}</b>${esc(t)}<span>${n}건</span></div>`).join('')||'<p class="empty">집계 대상 없음</p>'}</section><p class="sectionnote">집계 기준시각: ${date(now())} · 완료율 = 완료 건수 / 접수 건수 · 완료 건이 없으면 평균 처리시간 미표시</p>`}
function manage(){return heading('가이드 관리','장비별 증상과 조치 단계의 설명·이미지를 관리합니다. 변경된 내용은 새 안내부터 적용됩니다.',`<button class="btn" data-action="models">장비 모델 관리</button><button class="btn primary" data-action="newguide">${icon('plus')}가이드 추가</button>`)+`<section class="panel">${data.guides.map(g=>`<div class="listitem"><div><strong>${esc(g.title)}</strong><p>${types[g.type]} · ${g.steps.length}개 조치 단계 · 이미지 ${(g.stepImages||[]).filter(Boolean).length}장 · 버전 ${g.version||1}</p></div><button class="btn" data-edit="${g.id}">조치 단계 관리</button></div>`).join('')}</section><p class="sectionnote">시연 버전에서는 순차 질문과 미해결·수행 불가 분기를 제공합니다. 임의 분기 편집·게시 승인 기능은 실제 구축 시 확장 대상입니다.</p>`}
function render(){document.body.classList.toggle('stats-view',signedIn&&admin()&&page==='stats');document.body.classList.toggle('report-print-view',signedIn&&admin()&&['weekly','monthly'].includes(page));if(page!=='intro'&&!signedIn){pendingPage=page;page='intro';render();glassLogin();return;}if(page==='intro'){document.body.classList.remove('workspace-active');document.body.classList.add('intro-active');$('#app').innerHTML=intro();bindIntro();return;}document.body.classList.remove('intro-active');document.body.classList.add('workspace-active');if(!admin()&&['stats','manage','catalog','weekly','monthly'].includes(page))page='home';$('#app').innerHTML=shell();$('#content').innerHTML=({home,help,requests,stats,manage,toner,catalog,weekly:reports,monthly:reports}[page])()+`<footer class="footer"><span>일산차병원 · 온케어 IT 지원센터</span><span class="demo">시연 모드 · 병원 계정 미연동 · 이 브라우저에만 저장</span></footer>`;bind();}
function bind(){bindReports();bindToner();bindCatalog();document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$('#role').onchange=e=>{role=e.target.value;if(!admin()&&tonerTab==='ledger')tonerTab='requests';nav('home')};document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>chooseType(+b.dataset.type));document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>startGuide(b.dataset.guide));document.querySelectorAll('[data-detail]').forEach(b=>{b.onclick=()=>detail(b.dataset.detail);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();detail(b.dataset.detail)}}});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editGuide(b.dataset.edit));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-filter]').forEach(e=>e.onchange=()=>{filters[e.dataset.filter]=e.value;refreshView()});if($('#search'))$('#search').oninput=e=>{let p=e.target.selectionStart;filters.q=e.target.value;refreshView();$('#search').focus();$('#search').setSelectionRange(p,p)}}
function refreshView(){$('#content').innerHTML=({requests,stats}[page])()+`<footer class="footer"><span>일산차병원 IT 지원센터</span><span>시연 데이터 · 현재 브라우저에 저장</span></footer>`;bind()}
function action(a){if(!requireLogin('home'))return;if(a==='urgent'){wizard={urgent:true,type:0,history:[],version:0};requestForm()}if(a==='notifications')notifications();if(a==='newguide')editGuide(null);if(a==='models')manageModels();if(a==='resetfilters'){filters={q:'',status:'',type:'',dept:'',assignee:'',symptom:'',urgent:'',from:'',to:''};refreshView()}if(a==='export')exportExcel()}
function modal(title,body,foot=''){document.querySelector('#overlay').innerHTML=`<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><h2>${title}</h2><button class="close" aria-label="닫기">×</button></div><div class="modalbody">${body}</div>${foot?`<div class="modalfoot">${foot}</div>`:''}</section></div>`;$('.close').onclick=close;document.body.style.overflow='hidden';$('.close').focus();$('.modalback').onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){let f=[...$('.modal').querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled),a=f[0],b=f.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}}}
function close(){$('#overlay').innerHTML='';document.body.style.overflow='';}
function chooseType(type){if(!requireLogin('help'))return;selectDevice(type,device=>chooseSymptom(type,device))}
function chooseSymptom(type,device){modal(`${types[type]} · 증상 선택`,`<p class="subtitle">가장 가까운 증상을 선택해주세요.</p><div class="choices">${data.guides.filter(g=>g.type===type).map(g=>`<button class="choice" data-g="${g.id}">${esc(g.title)}<span>→</span></button>`).join('')}</div><div class="notice">목록에 없는 증상이 업무를 중단시키는 경우 긴급 접수를 이용해주세요.</div>`);document.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>startGuide(b.dataset.g,device));}
function startGuide(id,device=null){if(!requireLogin('help'))return;let g=data.guides.find(g=>g.id===id);if(!device)return selectDevice(g.type,d=>startGuide(id,d));wizard={urgent:false,brand:device.brand,model:device.model,type:g.type,title:g.title,guide:JSON.parse(JSON.stringify(g)),step:0,history:[],version:g.version||1,eligible:false};guideStep()}
function guideStep(){let w=wizard,g=w.guide;modal(g.title,`<div class="steps">${g.steps.map((_,i)=>`<span class="${i<=w.step?'on':''}"></span>`).join('')}</div><div class="notice" style="margin-top:0">${esc(deviceLabel(w))}</div><div class="stepnum">${types[w.type]} · STEP ${w.step+1} / ${g.steps.length}</div><h3>${w.step===0?'먼저 기본 상태를 확인해주세요.':'다음 조치를 확인해주세요.'}</h3><p class="guide-action-text" style="font-size:15px;line-height:1.9">${esc(g.steps[w.step])}</p>${stepPicture(g.stepImages?.[w.step],`조치 ${w.step+1} 참고 이미지`)}<div class="notice warm">조치가 어렵거나 안전상 수행할 수 없다면 ‘수행할 수 없어요’를 선택하세요. 본체를 분해하거나 진료에 영향을 주는 작업을 무리하게 진행하지 마세요.</div><p class="subtitle">확인 후 문제가 해결되었나요?</p>`,`<button class="btn" id="back" ${w.step===0?'disabled':''}>이전</button><button class="btn" id="cannot">수행할 수 없어요</button><button class="btn" id="unsolved">아직 해결되지 않았어요</button><button class="btn primary" id="solved">해결됐어요</button>`);$('#back').onclick=()=>{w.step--;w.history=w.history.slice(0,w.step);guideStep()};$('#cannot').onclick=()=>{modal('조치를 수행할 수 없는 이유',`<label for="skipreason">사유 <span class="required">*</span></label><textarea id="skipreason" placeholder="예: 진료 중이라 재시작할 수 없습니다."></textarea>`,`<button class="btn primary" id="skipconfirm">사유 기록 후 접수로 이동</button>`);$('#skipconfirm').onclick=()=>{let reason=$('#skipreason').value.trim();if(!reason)return toast('수행할 수 없는 이유를 입력해주세요.');w.history.push({step:g.steps[w.step],image:g.stepImages?.[w.step]?{...g.stepImages[w.step]}:null,answer:'수행 불가: '+reason});w.eligible=true;requestForm()}};$('#unsolved').onclick=()=>{w.history.push({step:g.steps[w.step],image:g.stepImages?.[w.step]?{...g.stepImages[w.step]}:null,answer:'미해결'});if(w.step<g.steps.length-1){w.step++;guideStep()}else{w.eligible=true;guideEnd()}};$('#solved').onclick=()=>{data.solved++;save();modal('문제가 해결되었어요',`<div style="text-align:center;padding:25px"><div style="font-size:45px;color:#168f78">✓</div><h2>다시 원활한 업무를 시작하세요.</h2><p class="subtitle" style="margin-top:15px">자가 해결 이력이 저장되었습니다. 문제가 재발하면 새 안내를 시작해주세요.</p></div>`,`<button class="btn primary" id="finish">확인</button>`);$('#finish').onclick=()=>{close();render()}}}
function guideEnd(){modal('전산 담당자에게 도움을 요청하세요',`<div class="notice">안내된 ${wizard.history.length}개 조치를 확인했지만 해결되지 않았습니다.<br>시도한 조치가 접수 내용에 자동으로 포함됩니다.</div><h3>${esc(wizard.title)}</h3><p class="subtitle">접수 후 우리 부서 신청현황에서 진행 상황을 확인할 수 있습니다.</p>`,`<button class="btn primary" id="continue">전산에 장애 접수하기 ${icon('arrow')}</button>`);$('#continue').onclick=requestForm}
function requestForm(){if(!requireLogin('help'))return;let w=wizard;if(!w.urgent&&!w.eligible)return;let u=user();modal(w.urgent?'긴급 장애 접수':'장애 접수',`<form id="requestform"><div class="notice ${w.urgent?'warm':''}">${w.urgent?'진료 중단·여러 장비 동시 장애 등 긴급 상황은 즉시 접수할 수 있습니다.':'자가 조치 이력이 담당자에게 함께 전달됩니다.'}</div><div class="formgrid"><div><label>신청자 · 사번</label><input readonly value="${u.name} · ${u.id}"></div><div><label>부서</label><input readonly value="${u.dept}"></div><div><label for="phone">연락처 <span class="required">*</span></label><input id="phone" name="phone" required placeholder="내선번호 또는 연락처" maxlength="40"></div><div><label for="location">발생 위치 <span class="required">*</span></label><input id="location" name="location" required placeholder="예: 외래 2층 간호사실" maxlength="100"></div>${w.urgent?`<div><label for="rtype">장비 종류</label><select id="rtype" name="type">${types.map((t,i)=>`<option value="${i}">${t}</option>`).join('')}</select></div><div><label for="rtitle">증상 <span class="required">*</span></label><input id="rtitle" name="title" required placeholder="발생한 증상을 입력해주세요" maxlength="120"></div><div class="full"><label for="reason">긴급 사유 <span class="required">*</span></label><select id="reason" name="reason"><option>진료 중단</option><option>여러 장비 동시 장애</option><option>주요 업무 중단</option><option>기타 긴급 사유</option></select></div>`:`<div class="full"><label>장비 · 증상</label><input readonly value="${types[w.type]} · ${esc(w.title)}"></div>`}<div class="full">${w.urgent?deviceFields(w.type,'urgentdevice'):`<label>제조사 · 모델</label><input readonly value="${esc(deviceLabel(w))}">`}</div><div class="full"><label for="asset">자산번호 또는 PC 이름 <span class="subtitle">(선택)</span></label><input id="asset" name="asset" placeholder="모르는 경우 비워두셔도 됩니다" maxlength="100"></div><div class="full"><label for="description">추가 설명 ${w.urgent?'· 기타 긴급 사유':''}</label><textarea id="description" name="description" maxlength="2000" placeholder="추가로 전달할 내용을 입력해주세요"></textarea></div><div class="full"><label for="photos">사진 첨부 <span class="subtitle">(선택 · 최대 3장, 각 2MB)</span></label><input type="file" id="photos" accept="image/png,image/jpeg,image/webp" multiple><p class="sectionnote">환자 이름·등록번호 등 환자정보가 포함되지 않은 사진만 첨부해주세요.</p></div></div>${!w.urgent?`<div class="notice">${guideHistoryMarkup(w.history)}</div>`:''}</form>`,`<button class="btn" id="cancelrequest">취소</button><button class="btn primary" id="submitrequest">${w.urgent?'긴급 접수하기':'접수하기'}</button>`);$('#cancelrequest').onclick=close;$('#submitrequest').onclick=submitRequest;if(w.urgent){w.readDevice=bindDeviceFields(w.type,'urgentdevice');$('#rtype').onchange=e=>{w.type=Number(e.target.value);let holder=$('#urgentdevice-brand').closest('.formgrid').parentElement;holder.innerHTML=deviceFields(w.type,'urgentdevice');w.readDevice=bindDeviceFields(w.type,'urgentdevice');};}}
async function submitRequest(){if(!requireLogin('help'))return;let form=$('#requestform');if(!form.reportValidity())return;let f=new FormData(form),w=wizard,device=w.urgent?w.readDevice():{brand:w.brand,model:w.model};if(!device)return;let files=[...$('#photos').files];if(w.urgent&&f.get('reason')==='기타 긴급 사유'&&!f.get('description').trim())return toast('기타 긴급 사유를 추가 설명에 입력해주세요.');if(files.length>3||files.some(f=>f.size>2*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)))return toast('사진은 JPG·PNG·WebP 각 2MB 이하로 3장까지 가능합니다.');if(!f.get('phone').trim()||!f.get('location').trim()||(w.urgent&&!f.get('title').trim()))return toast('필수 항목을 공백 없이 입력해주세요.');let btn=$('#submitrequest');btn.disabled=true;try{let images=await Promise.all(files.map(file=>new Promise((res,rej)=>{let reader=new FileReader();reader.onload=()=>res({name:file.name,url:reader.result});reader.onerror=rej;reader.readAsDataURL(file)})));let u=user(),id='IT-'+new Date().getFullYear()+'-'+String(Math.max(128,...data.requests.map(r=>Number(r.id.split('-')[2])))+1).padStart(4,'0'),at=now();let r={id,title:w.urgent?f.get('title').trim():w.title,type:w.urgent?Number(f.get('type')):w.type,brand:device.brand,model:device.model,dept:u.dept,name:u.name,user:u.id,phone:f.get('phone').trim(),location:f.get('location').trim(),asset:f.get('asset'),description:f.get('description'),urgent:w.urgent,reason:w.urgent?f.get('reason'):'',history:w.history,version:w.version,status:'접수',assignee:null,created:at,completed:null,images,events:[{text:'장애가 접수되었습니다.',at}],resolution:''};data.requests.unshift(r);try{save()}catch(e){data.requests.shift();throw e}try{notify(`${r.urgent?'[긴급] ':''}${r.id} · ${r.title}`,'admin')}catch{}close();page='requests';render();detail(id);toast('접수가 완료되었습니다. '+id)}catch{toast('저장 공간이 부족하거나 사진을 읽지 못했습니다. 사진 용량을 줄여 재시도해주세요.');if(btn.isConnected)btn.disabled=false}}
function detail(id){let r=visible().find(x=>x.id===id);if(!r)return;activeId=id;let u=user();modal(`${r.id} · 신청 상세`,`${r.urgent?'<span class="tag urgent">긴급 장애</span>':''}${tag(r.status)}<h3 style="font-size:20px;margin:20px 0">${esc(r.title)}</h3><dl class="kv"><dt>장비</dt><dd>${types[r.type]}</dd><dt>제조사</dt><dd>${esc(r.brand||'기존 접수 · 미입력')}</dd><dt>모델</dt><dd>${esc(r.model||'기존 접수 · 미입력')}</dd><dt>신청자</dt><dd>${esc(r.name)} · ${esc(r.dept)}</dd><dt>연락처</dt><dd>${esc(r.phone)}</dd><dt>발생 위치</dt><dd>${esc(r.location)}</dd><dt>장비 식별정보</dt><dd>${esc(r.asset||'미입력')}</dd><dt>접수일시</dt><dd>${date(r.created)}</dd>${r.urgent?`<dt>긴급 사유</dt><dd>${esc(r.reason)}</dd>`:''}<dt>추가 설명</dt><dd>${esc(r.description||'없음')}</dd><dt>담당자</dt><dd>${admin()&&r.status!=='완료'?`<select id="assign" aria-label="담당자 지정"><option value="">미배정</option>${['김전산','이전산'].map(n=>`<option ${r.assignee===n?'selected':''}>${n}</option>`).join('')}</select>`:esc(r.assignee||'미배정')}</dd></dl>${r.images?.length?`<div class="attachments">${r.images.map(f=>`<a href="${f.url}" target="_blank" rel="noopener"><img src="${f.url}" alt="${esc(f.name)}"></a>`).join('')}</div>`:''}<h3>자가 조치 이력 ${r.version?`<small style="color:#95aaa5">v${r.version}</small>`:''}</h3><div class="notice">${r.history.length?guideHistoryMarkup(r.history):r.sampleBatch?'통계 시연을 위해 생성한 가상 접수입니다.':r.urgent?'긴급 접수로 자가 조치를 생략했습니다.':'기존 전화 접수 시연 데이터입니다.'}</div><h3>처리 이력</h3><div class="timeline">${r.events.map(e=>`<p>${esc(e.text)}<small>${date(e.at)}</small></p>`).join('')}</div>${r.status==='완료'?`<h3>완료 조치</h3><div class="notice">${esc(r.resolution)}</div>`:admin()&&r.assignee===u.name&&r.status==='처리 중'?'<label for="resolution">완료 조치 내용 <span class="required">*</span></label><textarea id="resolution" placeholder="확인한 원인과 조치 결과를 입력해주세요"></textarea>':''}`,admin()&&r.assignee===u.name&&r.status!=='완료'?`<button class="btn primary" id="statuschange">${r.status==='접수'?'처리 시작':'조치 입력 후 완료'}</button>`:'');if($('#assign'))$('#assign').onchange=e=>{r.assignee=e.target.value||null;r.events.push({text:`${u.name}: 담당자 ${r.assignee||'미배정'}로 변경`,at:now()});save();if(r.assignee)notify(`${r.id} · 담당자가 ${r.assignee}님으로 지정되었습니다.`,'admin');render();detail(id)};if($('#statuschange'))$('#statuschange').onclick=()=>{if(r.status==='접수'){r.status='처리 중';r.events.push({text:`${u.name}: 처리를 시작했습니다.`,at:now()})}else{let text=$('#resolution').value.trim();if(!text)return toast('완료 조치 내용을 입력해주세요.');r.status='완료';r.resolution=text;r.completed=now();r.events.push({text:`${u.name}: 처리를 완료했습니다.`,at:now()})}save();if(r.user==='N1024')notify(`${r.id} · ${r.status==='완료'?'처리가 완료되었습니다.':'담당자가 처리를 시작했습니다.'}`);render();detail(id);toast('처리 상태를 저장했습니다.')}}
function notifications(){let notes=mynotes();modal('알림',notes.length?notes.map(n=>`<div class="listitem"><div><strong style="font-size:12px">${n.read?'':'● '}${esc(n.message)}</strong><p>${date(n.at)}</p></div></div>`).join(''):'<div class="empty">새로운 알림이 없습니다.<br>접수·배정·처리 결과가 여기에 표시됩니다.</div>',notes.length?'<button class="btn primary" id="readall">모두 읽음</button>':'');if($('#readall'))$('#readall').onclick=()=>{notes.forEach(n=>n.read=true);save();close();render()}}
function exportExcel(){
 if(!admin())return;
 let rows=filtered(),done=rows.filter(r=>r.status==='완료'),avg=done.length?done.reduce((s,r)=>s+(new Date(r.completed)-new Date(r.created))/3600000,0)/done.length:null;
 let sheets=[{name:'집계 요약',rows:[['온케어 장애 현황'],['기준시각',date(now())],['집계 기준','접수일 기준 · KST · 야간 및 휴일 포함'],['필터',JSON.stringify(filters)],[],['접수 건수','미완료 건수','완료 건수','완료율','평균 처리시간(시간)'],[rows.length,rows.length-done.length,done.length,rows.length?(done.length/rows.length*100).toFixed(1)+'%':'집계 대상 없음',avg===null?'집계 대상 없음':Number(avg.toFixed(2))],[],['장비','접수 건수'],...types.map((t,i)=>[t,rows.filter(r=>r.type===i).length]),[],['부서','접수 건수'],...[...new Set(rows.map(r=>r.dept))].map(d=>[d,rows.filter(r=>r.dept===d).length]),[],['증상','접수 건수'],...Object.entries(rows.reduce((a,r)=>(a[r.title]=(a[r.title]||0)+1,a),{}))]}, {name:'접수 목록',rows:[['접수번호','장비','제조사','모델','증상','부서','발생 위치','상태','담당자','긴급 여부','접수일시','완료일시'],...rows.map(r=>[r.id,types[r.type],r.brand||'미입력',r.model||'미입력',r.title,r.dept,r.location,r.status,r.assignee||'미배정',r.urgent?'긴급':'일반',date(r.created),r.completed?date(r.completed):''])]}];
 let url=URL.createObjectURL(makeXlsx(sheets)),a=document.createElement('a');a.href=url;a.download='온케어_장애통계.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('통계 및 접수 목록을 다운로드했습니다.');
}
